from pathlib import Path
from datetime import datetime,timezone
import json,hashlib,subprocess,sys
H=Path(__file__).resolve().parent
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
freeze=json.loads((H/'analysis-freeze.json').read_text());assert all(sha(H/k)==v for k,v in freeze['source_hashes'].items())
for script in ['run_analysis.py','check_normal.py']:subprocess.run([sys.executable,str(H/script)],check=True)
plan=json.loads((H/'study-plan.json').read_text());d=json.loads((H/'diagnostics.json').read_text())['results'];normal=json.loads((H/'normal-diagnostic.json').read_text())['results'];results={}
for arm in plan['generator_arms']:
    v=d[arm];pp=json.loads((H/arm/'pilot-plan.json').read_text());assert all(sha(H/arm/n)==z==sha(H.parent/'bet_size_realism_20260910/sized'/n) for n,z in pp['source_hashes'].items());replay=json.loads((H/arm/'intervention-replay-audit.json').read_text());results[arm]={'soft_source_auc':v['source_auc'],'none_source_auc':normal[arm]['source_auc'],'calling':v['action_summary']['preflop']['equal_pair_mean_fold_check_call_raise'][2],'call_strength':v['conditional']['preflop_calls']['own_strength'],'supported_pairs':v['supported_pairs'],'passes':v['realism_gate_passed'] and normal[arm]['passes_ceiling'],'verified_changes':replay['counterfactual_action_changes_verified'],'replayed_hands':replay['hands']}
assert all(sha(H.parents[1]/n)==z for n,z in plan['protected'].items());passed=all(v['passes'] for v in results.values());out={'at':datetime.now(timezone.utc).isoformat(),'all_confirmation_gates_passed':passed,'all_generator_bytes_unchanged':True,'results':results,'no_new_utility_score':True,'protected_submissions_unchanged':True,'next_step':'One frozen utility study using all three size populations and all fixed resampling controls.' if passed else 'Keep the failed confirmation. Training-only diagnosis; no size utility trial.'};(H/'summary.json').write_text(json.dumps(out,indent=2));lines=['# Unchanged conditional-size confirmation','',('PASS' if passed else 'FAIL')+' across both prescribed populations.','', '| Population | Soft-play source AUC | None source AUC | Calling | Call strength | Gate |','|---|---:|---:|---:|---:|---|']
for a,v in results.items():lines.append(f"| {a} | {v['soft_source_auc']:.6f} | {v['none_source_auc']:.6f} | {v['calling']:.6f} | {v['call_strength']:.6f} | {'PASS' if v['passes'] else 'FAIL'} |")
lines+=['','All192,000 histories pass legal/accounting audits, and every intervention is independently checked. One population is a paired development replay and one uses unused seeds. Model/environment/sampler bytes match the initial pilot. These policies share original training data; they are not independent real-world sources.','',out['next_step'],'','The earlier capacity-only utility failure is preserved. No new outer-held score, VM, upload or production change.',''];(H/'RESULTS.md').write_text('\n'.join(lines),encoding='utf-8');print(json.dumps(out,indent=2))
